∀ {k : Type u_1} [inst : Field.{u_1} k] {n : Nat} (i : Fin n)
  (s : Subtype.{u_1 + 1} fun x => Membership.mem.{u_1, u_1} (Etingof.upperTriangularSubalgebra.{u_1} k n) x)
  (v : Etingof.UpperTriangularSimple.{u_1} k n i),
  Eq.{u_1 + 1} (HSMul.hSMul.{u_1, u_1, u_1} s v)
    (HMul.hMul.{u_1, u_1, u_1}
      (have this := Subtype.val.{u_1 + 1} s i i;
      this)
      (have this := v;
      this))

∀ {k : Type u_1} [inst : Field.{u_1} k] {n : Nat} (M : Type u_2) [inst_1 : AddCommGroup.{u_2} M]
  [inst_2 :
    Module.{u_1, u_2}
      (Subtype.{u_1 + 1} fun x => Membership.mem.{u_1, u_1} (Etingof.upperTriangularSubalgebra.{u_1} k n) x) M]
  [IsSimpleModule.{u_1, u_2}
      (Subtype.{u_1 + 1} fun x => Membership.mem.{u_1, u_1} (Etingof.upperTriangularSubalgebra.{u_1} k n) x) M],
  Exists.{1} fun i =>
    Nonempty.{max (u_1 + 1) (u_2 + 1)}
      (LinearEquiv.{u_1, u_1, u_2, u_1}
        (RingHom.id.{u_1}
          (Subtype.{u_1 + 1} fun x => Membership.mem.{u_1, u_1} (Etingof.upperTriangularSubalgebra.{u_1} k n) x))
        M (Etingof.UpperTriangularSimple.{u_1} k n i))

∀ (k : Type u_1) [inst : Field.{u_1} k] (n : Nat) {i j : Fin n},
  Ne.{1} i j →
    Not
      (Nonempty.{u_1 + 1}
        (LinearEquiv.{u_1, u_1, u_1, u_1}
          (RingHom.id.{u_1}
            (Subtype.{u_1 + 1} fun x => Membership.mem.{u_1, u_1} (Etingof.upperTriangularSubalgebra.{u_1} k n) x))
          (Etingof.UpperTriangularSimple.{u_1} k n i) (Etingof.UpperTriangularSimple.{u_1} k n j)))
